import unittest
from solution import parse_timestamp

class TestParseTimestamp(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(parse_timestamp('[2024-03-14T09:26:53Z] ERROR: timeout'), '2024-03-14T09:26:53Z')

    def test_no_timestamp(self):
        self.assertIsNone(parse_timestamp('plain log line with no date'))

    def test_empty_string(self):
        self.assertIsNone(parse_timestamp(''))

    def test_offset_timezone(self):
        result = parse_timestamp('2026-01-01T12:00:00+08:00 INFO started')
        self.assertEqual(result, '2026-01-01T12:00:00+08:00')

if __name__ == '__main__':
    unittest.main()
